using HakutaiKagami.Core.Contracts;
using Xunit;
using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Tests;
public sealed class PersonalWithdrawalTests
{
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static NewMilitaryInput I(WorldSession s,NewMilitaryAction a)=>new(new("request:withdrawal/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(I(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var r=s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static WorldSession Away(){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);return s;}
    static void PersonEnd(WorldSession s)=>At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Last().EndAt+1);
    [Fact]public void CargoMustBeHandedOver(){var s=Ready();Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.Withdraw),s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Handoff);Assert.Equal(NewGameMilitary.UnitIds[0],s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==NewGameMilitary.Carry).MobileHolder);}
    [Fact]public void DepartureDoesNotTeleportUnitsOrCargo(){var s=Away();var w=s.DiagnosticSnapshot();var p=NewGameMilitary.Position(w,0,s.Seconds);var cargo=FieldSupply.Location(w,w.ResourceLots.Single(l=>l.Id==NewGameMilitary.Carry));PersonEnd(s);w=s.DiagnosticSnapshot();Assert.Equal(p,NewGameMilitary.Position(w,0,s.Seconds));Assert.Equal(NewGameMilitary.Home(w,0),NewGameMilitary.PersonPosition(w,s.Seconds));Assert.Equal(cargo,FieldSupply.Location(w,w.ResourceLots.Single(l=>l.Id==NewGameMilitary.Carry)));Assert.All(w.Units,u=>Assert.Equal(s.PlayerControl,u.Commander));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.Enter),s.PlayerControl,s.Revision).Code);}
    [Fact]public void RecallOnlyExecutesOnArrival(){var s=Away();PersonEnd(s);var n=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();Assert.Equal(n,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);At(s,d.DueAt-1);Assert.Equal(n,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);At(s,d.DueAt);Assert.Equal(n+1,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);Assert.Contains("未受領",NewGameMilitary.PersonalStatus(s.DiagnosticSnapshot()));At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);Assert.Contains("受令返書を受領",NewGameMilitary.PersonalStatus(s.DiagnosticSnapshot()));}
    [Fact]public void DepartedSenderDoesNotReceiveReply(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);Send(s,NewMilitaryAction.Rejoin);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single().DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Replies.Single().Received);}
    [Fact]public void NoTelepathicLocalOrdersOrReports(){var s=Away();PersonEnd(s);foreach(var a in new[]{NewMilitaryAction.Hold,NewMilitaryAction.Recall,NewMilitaryAction.Report,NewMilitaryAction.Reclaim,NewMilitaryAction.CombatStart})Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,a),s.PlayerControl,s.Revision).Code);}
    [Fact]public void RejoinRequiresPhysicalAttachment(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.Rejoin);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.Attach),s.PlayerControl,s.Revision).Code);PersonEnd(s);Send(s,NewMilitaryAction.Attach);Assert.False(NewGameMilitary.Detached(s.DiagnosticSnapshot()));Send(s,NewMilitaryAction.Reclaim);Assert.False(NewGameMilitary.UnitCarries(s.DiagnosticSnapshot()));}
    [Fact]public void DetachedSupplyConsumptionIsConserved(){var s=Away();long n=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;At(s,s.Seconds+5);Assert.Equal(n-500,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);}
    [Fact]public void RetryDoesNotDuplicateJourney(){var s=Ready();Send(s,NewMilitaryAction.Handoff);var i=I(s,NewMilitaryAction.Withdraw);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(3)][InlineData(10)]public void PersonalJourneyRestoresSameFuture(int seconds){var s=Away();At(s,s.Seconds+seconds);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c}){PersonEnd(x);Send(x,NewMilitaryAction.RemoteRecall);At(x,x.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+25);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(3)]public void CourierRestoresSameFuture(int seconds){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.Seconds+seconds);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c})At(x,x.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+25);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedPhysicalHistoryRejected(int kind){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.Withdrawal!;if(kind==0)x.Journeys[0]=x.Journeys[0] with{Origin=new(0,0)};if(kind==1)x.Dispatches[0]=x.Dispatches[0] with{Destination=NewGameMilitary.Home(w,0)};if(kind==2)x.Dispatches[0]=x.Dispatches[0] with{Recipient=w.PlayerControl};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldSaveOmitsOptionalModule(){var s=Ready();var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("Withdrawal",text);Assert.Null(ContractJson.Read<NewMilitaryState>(System.Text.Encoding.UTF8.GetBytes(text)).Withdrawal);}
    [Fact]public void MovingArmyContinuesItsReceivedOrderAfterPersonLeaves(){var s=Ready();var w=s.DiagnosticSnapshot();var a=NewGameMilitary.Anchor(w);var r=s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+60000,a.Y),B=new(a.X+60000,a.Y+16000)},s.PlayerControl,s.Revision);Assert.Equal(ResultCode.Accepted,r.Code);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var p=NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds);At(s,s.Seconds+3);Assert.NotEqual(p,NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds));Assert.NotEqual(NewGameMilitary.PersonPosition(s.DiagnosticSnapshot(),s.Seconds),NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds));}
    [Fact]public void UnknownNewUnitLocationIsNotUsedAsCourierAddress(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+60000,a.Y),B=new(a.X+60000,a.Y+16000)},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var known=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Sightings.Last().Position;PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();Assert.Equal(known,d.Destination);Assert.NotEqual(NewGameMilitary.Position(s.DiagnosticSnapshot(),0,s.Seconds),d.Destination);At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last().Delivered);}
    [Fact]public void DistantLocalObservationIsRejected(){var s=Away();PersonEnd(s);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.Observe),s.PlayerControl,s.Revision).Code);}
    [Fact]public void ForgedReceiptOutcomeCannotStartRetreat(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt);var w=s.DiagnosticSnapshot();w.NewMilitary!.Withdrawal!.Receipts[0]=w.NewMilitary.Withdrawal.Receipts[0] with{Delivered=false};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ForgedReplyReceptionCannotCreateKnowledge(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last().ReplyDueAt);var w=s.DiagnosticSnapshot();w.NewMilitary!.Withdrawal!.Replies[0]=w.NewMilitary.Withdrawal.Replies[0] with{Received=false};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ReturnRequestAloneDoesNotHandBackCommand(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);var w=s.DiagnosticSnapshot();Assert.DoesNotContain(w.NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);Assert.All(w.Units,u=>Assert.Equal(w.PlayerControl,u.Commander));}
    [Fact]public void PersonalRetreatDoesNotInventACharacterOrAlterDefinitions(){var s=Ready();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions);int n=s.DiagnosticSnapshot().Characters.Length;Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+1);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot().Definitions));Assert.Equal(n,s.DiagnosticSnapshot().Characters.Length);}

    [Fact]public void StaleRejoinCanReturnHomeAndFindLastOrderedPost(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());var target=new FieldPoint(a.X+60000,a.Y);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=target,B=new(a.X+60000,a.Y+16000)},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);PersonEnd(s);Send(s,NewMilitaryAction.Rejoin);PersonEnd(s);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.Attach),s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.PersonalHome);PersonEnd(s);Assert.Equal(NewGameMilitary.Home(s.DiagnosticSnapshot(),0),NewGameMilitary.PersonPosition(s.DiagnosticSnapshot(),s.Seconds));var r=s.DecideNewMilitary(I(s,NewMilitaryAction.PersonalMove) with{A=target},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);At(s,s.Seconds+1);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,copy}){PersonEnd(x);Send(x,NewMilitaryAction.Attach);}Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Fact]public void PersonalHomeRestoresWithoutChangingUnitOrders(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.Rejoin);PersonEnd(s);int n=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.PersonalHome);At(s,s.Seconds+1);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,copy})PersonEnd(x);Assert.Equal(n,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Fact]public void PersonalMoveRejectsFarPointWithoutMutation(){var s=Away();PersonEnd(s);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.PersonalMove) with{A=new(a.X+120001,a.Y)},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}

    [Theory][InlineData(long.MaxValue,long.MaxValue)][InlineData(long.MinValue,long.MinValue)][InlineData(long.MaxValue,long.MinValue)]public void ExtremePersonalCoordinatesCannotWrapIntoExercise(long x,long y){var s=Away();PersonEnd(s);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(I(s,NewMilitaryAction.PersonalMove) with{A=new(x,y)},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}

    [Fact]public void StaleRecallCannotOverrideNewerLocalPlan(){var s=Ready();Send(s,NewMilitaryAction.Recall);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);Send(s,NewMilitaryAction.RemoteRecall);Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Hold);int n=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;At(s,s.Seconds+1);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last();Assert.True(r.Delivered);Assert.False(r.Applied);Assert.Equal(n,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,copy})At(x,x.Seconds+1);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}

    [Fact]public void UnitOriginalAttemptAndEffectUseSeparateIds(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();Assert.NotEqual(d.Id.Value,d.Message);Assert.NotEqual(d.Message,d.Attempt);Assert.Equal(d.Message,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,d.Message).MessageId);At(s,d.DueAt);Assert.NotEqual(d.Id,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Id);}
    [Fact]public void SharedFormalReceiptDoesNotInventACharacter(){var s=Away();PersonEnd(s);int count=s.DiagnosticSnapshot().Characters.Length;Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==d.Message);At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.Contains(w.Messaging.Receipts,r=>r.MessageId==d.Message&&r.PrincipalId==NewGameMilitary.UnitIds[0].Value);Assert.Equal(count,w.Characters.Length);Assert.All(w.Evidence,e=>Assert.Contains(w.Characters,c=>c.Id==e.Observer));}
    [Fact]public void CommonFailureIsKnownOnlyAfterItsPhysicalReturn(){var s=Ready();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(I(s,NewMilitaryAction.Form) with{A=new(a.X+60000,a.Y),B=new(a.X+60000,a.Y+16000)},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();At(s,d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last();Assert.False(r.Delivered);Assert.False(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,d.Attempt,s.PlayerControl.Value));At(s,r.ReplyDueAt);Assert.True(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,d.Attempt,s.PlayerControl.Value));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedCommonUnitEnvelopeRejected(int kind){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var w=s.DiagnosticSnapshot();var d=w.NewMilitary!.Withdrawal!.Dispatches.Last();w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id!=d.Message?m:kind==0?m with{Body=m.Body.Replace("recall","hold")}:kind==1?m with{Scope="site:odawara"}:m with{RecipientId=w.PlayerControl.Value}).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ForgedSharedReplyBodyRejected(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt);var w=s.DiagnosticSnapshot();var r=w.NewMilitary!.Withdrawal!.Receipts.Last();w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==r.ReplyMessage?m with{Body="{}"}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void RepeatedUnitOrdersHaveRestorableCommonTransport(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Last().ReplyDueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Send(s,NewMilitaryAction.Observe);Send(s,NewMilitaryAction.RemoteRecall);At(s,s.Seconds+1);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,copy})At(x,x.Seconds+1);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));Assert.Equal(2,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Replies.Length);}

    [Fact]public void DiagnosticPayloadTamperingIsRejectedAtomically(){var s=Away();PersonEnd(s);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>m.Messages=m.Messages.Select(x=>x.Id==d.Message?x with{Body="{}"}:x).ToArray()));Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}

}
